@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#121713;--paper:#f0f0e9;--muted:#a0a69c;--green:#c8f169;--orange:#ff875f;--line:rgba(232,239,223,.12);--mono:'DM Mono',monospace;--display:'Space Grotesk',sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#0b100d;color:var(--paper);font-family:var(--display);display:grid;place-items:center;padding:22px;overflow-x:hidden}.app-shell{width:min(1440px,100%);margin:auto}.game-frame{position:relative;min-height:min(850px,calc(100vh - 44px));height:min(850px,calc(100vh - 44px));min-width:320px;overflow:hidden;background:#151b17;border:1px solid #29312a;box-shadow:0 40px 100px #0009;isolation:isolate}.noise{position:absolute;inset:0;z-index:5;pointer-events:none;opacity:.09;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}.topbar{height:68px;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 5.2%;position:relative;z-index:6}.brand{text-decoration:none;color:var(--paper);font-size:15px;letter-spacing:.15em;font-weight:700;display:flex;align-items:center;gap:10px}.brand-mark{display:grid;place-items:center;background:var(--green);color:#182116;width:27px;height:27px;font-size:15px;letter-spacing:0;font-weight:700;clip-path:polygon(0 0,100% 0,100% 72%,72% 100%,0 100%)}.brand-dot{color:var(--green)}.top-status{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:13px;font:9px var(--mono);letter-spacing:.12em;color:#9da49a;white-space:nowrap}.status-pill{display:flex;gap:7px;align-items:center;color:#c5d0bf}.status-pill i,.live-dot{height:6px;width:6px;border-radius:50%;background:var(--green);display:inline-block;box-shadow:0 0 10px #c8f16680}.tiny-divider{width:1px;height:12px;background:#4b544b}.season b{col