:top}.arm-back{left:34px;transform:rotate(28deg);background:#a76e54}.arm-front{left:95px;transform:rotate(-40deg)}.man-gun{position:absolute;z-index:4;width:72px;height:13px;top:105px;left:85px;background:#252b26;border-radius:2px;transform:rotate(-5deg);box-shadow:0 -4px 0 -1px #41483c}.man-gun:before{content:'';position:absolute;left:16px;top:8px;width:9px;height:17px;background:#30362d;transform:rotate(10deg)}.man-gun i{position:absolute;right:-13px;top:4px;width:14px;height:4px;background:#161b17}.man-pack{position:absolute;top:83px;left:24px;width:30px;height:78px;background:#555b3d;border:3px solid #343a2b;border-radius:10px;z-index:-1}.hero-crate{position:absolute;z-index:2;bottom:13%;width:62px;height:50px;background:#79683e;border:4px solid #514a31;box-shadow:inset 0 0 0 2px #a0884d}.hero-crate:after{content:'';position:absolute;inset:0;background:linear-gradient(45deg,transparent 47%,#3b3e2d 48% 53%,transparent 54%)}.crate-one{left:12%;transform:scale(.8)}.crate-two{right:11%;bottom:8%;transform:scale(.7)}.home-bottom{position:absolute;z-index:4;bottom:0;left:0;right:0;height:58px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 5.2%;background:#141a16a6}.run-stats{display:flex;gap:22px;font:8px var(--mono);color:#7e887b;letter-spacing:.1em}.run-stats span b{color:#d4dacf;font-weight:500;margin-right:5px}.run-stats span:first-child b{color:var(--green)}.quit-link{background:none;border:0;color:#899185;font:9px var(--mono);letter-spacing:.1em;cursor:pointer}.quit-link span{font-size:14px;margin-left:7px}.update-chip{position:absolute;z-index:4;top:19px;right:5.2%;font:8px var(--mono);letter-spacing:.1em;color:#c1cbb9;display:flex;align-items:center;gap:7px}.update-chip b{color:var(--green)}.update-chip button{background:none;border:0;color:var(--green);font:8px var(--mono);letter-spacing:.1em;cursor:pointer;margin-left:4px}.update-pulse{width:5px;height:5px;background:var(--orange);border-radius:50%}
/* battle screen */
.game-screen{padding:24px 5.2% 16px;background:radial-gradient(ellipse at 51% 45%,#34402f 0,#202a21 47%,#161d18 83%);display:none;grid-template-rows:35px 94px minmax(200px,1fr) 83px 81px;gap:12px}.game-screen.active{display:grid}.game-top-controls{display:flex;align-items:center;gap:13px}.square-control{height:31px;width:34px;background:#262f28;border:1px solid #455044;color:#d8e0d1;cursor:pointer;font-size:14px}.game-brand{font:9px var(--mono);letter-spacing:.12em;color:#aab3a4;display:flex;align-items:center;gap:8px}.game-brand b{color:#e2e8dd;font-weight:500}.run-divider{color:#566252}.shop-button{margin-left:auto;background:var(--green);border:0;height:33px;padding:0 13px;color:#172014;font:700 9px var(--mono);letter-spacing:.1em;display:flex;align-items:center;gap:8px;cursor:pointer}.shop-button:hover{background:#dcff94}.shop-bag{font-size:13px}.shop-count{font:9px var(--mono);background:#11180f24;padding:4px 5px}.hud-row{display:flex;gap:12px}.hud-card{background:#202922d9;border:1px solid #3a463a;padding:12px 15px;position:relative;overflow:hidden}.level-card{width:42%;}.survivor-card{flex:1}.hud-label,.bottom-label{display:block;font:8px var(--mono);letter-spacing:.12em;color:#909b8c}.level-main{display:flex;align-items:center;gap:8px;margin-top:2px}.level-number{font-size:36px;font-weight:700;line-height:1;letter-spacing:-.07em;color:#f0f2e9}.level-meta{display:flex;flex-direction:column;gap:2px;font:8px var(--mono);letter-spacing:.09em;color:#838e7f}.level-meta b{color:var(--green);font-size:8px}.level-progress{height:3px;background:#111711;margin-top:8px}.level-progress i{height:100%;width:0;display:block;background:var(--green);transition:width .25s}.progress-caption{display:flex;justify-content:space-between;margin-top:5px;font:7px var(--mono);color:#899487;letter-spacing:.08em}.survivor-heading{display:flex;justify-content:space-between;align-items:center}.survivor-name{font:9px var(--mono);letter-spacing:.11em;color:#d8e0d4}.health-track{height:6px;margin-top:14px;background:#111711;clip-path:polygon(0 0,100% 0,98% 100%,0 100%)}.health-track i{height:100%;display:block;width:100%;background:linear-gradient(90deg,#c8f169,#98c84d);transition:width .25s}.health-caption{display:flex;justify-content:space-between;margin-top:7px;font:8px var(--mono);letter-spacing:.08em;color:#a0aa98}.health-caption>span:first-child{color:#ef9279}.health-caption b{color:#e2e9dc}.coin-caption{color:var(--green)}
