7}.luck-card>div{display:flex;flex-direction:column;gap:5px}.luck-card>div>b{font-size:14px}.luck-card small{font:7px var(--mono);color:#9ba596}.roll-button{position:relative;border:1px solid #f6be57;background:#e9a945;color:#1b1b13;font:700 9px var(--mono);letter-spacing:.08em;cursor:pointer;display:flex;justify-content:center;align-items:center;gap:7px;flex-wrap:wrap;transition:.2s}.roll-button:hover{background:#ffd06d;transform:translateY(-1px)}.roll-button:disabled{opacity:.42;cursor:not-allowed;filter:grayscale(.4)}.roll-button>span:nth-child(2){align-self:flex-end;margin-bottom:26px}.roll-button small{position:absolute;bottom:10px;left:0;right:0;font:7px var(--mono);letter-spacing:.1em;opacity:.68}.dice-face{font-size:21px;align-self:flex-end;margin-bottom:19px}.game-bottom{display:flex;align-items:end;gap:14px;border-top:1px solid var(--line);padding-top:10px}.difficulty-pick{min-width:225px}.bottom-label{font-size:7px;margin-bottom:6px}.difficulty-options{display:flex;gap:4px}.difficulty-option{border:1px solid #465044;background:#202821;color:#aab3a5;padding:6px 9px;font:8px var(--mono);letter-spacing:.07em;cursor:pointer}.difficulty-option span{color:#73806e;margin-right:5px}.difficulty-option.selected{background:#34432f;border-color:#849859;color:var(--green)}.difficulty-option.selected span{color:#c8f169}.run-tip{display:flex;align-items:center;gap:8px;margin:auto 0 auto 0;color:#d9e1d3}.tip-icon{font-size:17px;color:var(--green)}.run-tip span:last-child{display:flex;flex-direction:column;gap:4px}.run-tip b{font:7px var(--mono);letter-spacing:.08em}.run-tip small{color:#8f9a8b;font-size:8px}.exit-game{margin-left:auto;border:0;background:none;color:#919b8d;font:8px var(--mono);letter-spacing:.1em;cursor:pointer;white-space:nowrap}.exit-game span{font-size:13px;margin-left:4px}.mobile-controls{display:none}
/* modal */
.modal-backdrop{position:absolute;inset:0;z-index:20;background:#080d0bd9;display:none;place-items:center;padding:20px;backdrop-filter:blur(6px)}.modal-backdrop.open{display:grid}.modal{position:relative;width:min(440px,100%);padding:33px;background:#202922;border:1px solid #53604e;box-shadow:0 24px 80px #0009}.modal:before{content:'';position:absolute;top:-1px;left:32px;width:42px;height:2px;background:var(--green)}.modal-close{position:absolute;right:16px;top:14px;background:none;border:0;color:#9fa99b;font-size:23px;cursor:pointer}.modal-eyebrow{font-size:8px}.modal h2{font-size:28px;letter-spacing:-.04em;margin:10px 0 23px}.setting-row{padding:14px 0;border-top:1px solid #3b463c;display:flex;justify-content:space-between;align-items:center}.setting-label{display:flex;flex-direction:column;gap:5px}.setting-label b{font-size:12px;font-weight:600}.setting-label small{font:8px var(--mono);color:#929d8e}.toggle{width:38px;height:21px;padding:3px;background:#4d584a;border:0;border-radius:20px;cursor:pointer;transition:.2s}.toggle:after{content:'';display:block;width:15px;height:15px;border-radius:50%;background:#dfe4d8;transition:.2s}.toggle.on{background:#87a749}.toggle.on:after{transform:translateX(17px);background:#f2ffdc}.name-input{width:145px;background:#151c16;border:1px solid #455143;padding:9px;color:#e7ece2;font:10px var(--mono);outline:none}.name-input:focus{border-color:var(--green)}.modal-action{width:100%;margin-top:17px;padding:12px;background:var(--green);border:0;color:#172014;font:700 9px var(--mono);letter-spacing:.11em;cursor:pointer}.setting-note{font:8px var(--mono);line-height:1.6;color:#818c7e;margin-top:14px}.shop-balance{display:flex;justify-content:space-between;align-items:center;background:#151d16;padding:12px 14px;margin-bottom:13px;font:8px var(--mono);letter-spacing:.08em;color:#aab4a5}.shop-balance b{font:600 16px var(--display);color:var(--green)}.shop-item{border-top:1px solid #3b463c;padding:12px 0;display:flex;align-items:center;ju